using System;using System.Diagnostics;using System.IO;using System.Linq;
static class NetworkFactsTests {
 static void Check(bool value,string text){if(!value)throw new Exception(text);Console.WriteLine("PASS: "+text);}
 public static void Run(){var metrics=new ConnectionMetrics();metrics.ObserveState("Connected");long t=Stopwatch.Frequency;metrics.TrafficAt(1000,2000,t);metrics.TrafficAt(3048,3024,t*2);var snapshot=metrics.Snapshot();Check(snapshot.DownloadSpeed==2048&&snapshot.UploadSpeed==1024,"Live speed uses byte deltas and elapsed seconds");metrics.TrafficAt(0,0,t*3);Check(metrics.Snapshot().DownloadSpeed==null,"Counter reset cannot create a negative speed");metrics.ObserveState("Disconnected");Check(metrics.Snapshot().UploadSpeed==null,"Disconnected state hides stale transfer speeds");
 var routes=new[]{new AdapterRoute{Index=7,Family=2,Prefix="0.0.0.0",Length=1},new AdapterRoute{Index=7,Family=2,Prefix="128.0.0.0",Length=1},new AdapterRoute{Index=8,Family=2,Prefix="10.0.0.0",Length=8}};Check(RouteReader.Mode(routes,7,2)=="Full"&&RouteReader.Mode(routes,8,2)=="Split"&&RouteReader.Mode(routes,7,23)=="None","Routing detects paired default halves and separates IP families/interfaces");var system=RouteReader.Read();Check(system.Length>0&&system.All(r=>r.Length>=0&&r.Length<=(r.Family==2?32:128)),"Native Windows route table is decoded with valid prefix lengths");
 Check(VpnSession.EndpointHost("[2001:db8::1]:51820")=="2001:db8::1"&&VpnSession.EndpointHost("vpn.example.test:1194")=="vpn.example.test","Server endpoint parsing supports hostname and IPv6");string file=Path.GetTempFileName();try{File.WriteAllText(file,"<key>\nprivate material\n</key>\nremote vpn.example.test 1194\n");Check(VpnSession.ConfiguredServer(file,"OpenVPN")=="vpn.example.test","Profile parser extracts only the configured server hostname");}finally{File.Delete(file);}
 }
}
